  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 Atomic Structure and Isotopes$j$, $j${"readings": [{"title": "Hebrews 11 (King James Version)", "url": "/portal/bible/Hebrews/11"}], "body": "Everything you can touch is built from tiny particles. Hebrews 11:3 says, Through faith we understand that the worlds were framed by the word of God, so that things which are seen were not made of things which do appear. Atoms are too small to see, yet they are the building blocks of the visible world.\n\nAn atom has a small, dense center called the nucleus, which holds protons and neutrons. A proton has a positive charge. A neutron has no charge. Electrons have a negative charge and move around the nucleus in a region called the electron cloud. A proton and a neutron each have a mass of about 1 atomic mass unit, while an electron has only about one eighteen hundredth of that. An atom is mostly empty space.\n\nOur picture of the atom grew over time. Dalton described atoms as tiny solid spheres. Thomson discovered the electron. Rutherford shot particles at gold foil and found that most passed straight through while a few bounced back, which showed a tiny dense nucleus. Bohr proposed energy levels, and the modern model describes an electron cloud.\n\nThe atomic number is the number of protons, and it identifies the element. The mass number is the number of protons plus the number of neutrons. A neutral atom has equal numbers of protons and electrons. Sodium has atomic number 11 and mass number 23, so it has 11 protons, 11 electrons and 23 minus 11, or 12, neutrons.\n\nIsotopes are atoms of the same element with different numbers of neutrons. Carbon 12 has 6 protons and 6 neutrons. Carbon 14 has 6 protons and 8 neutrons. The atomic mass on the periodic table is an average of the isotopes. An ion forms when an atom gains or loses electrons. Losing an electron makes a positive ion, and gaining one makes a negative ion.\n\nYour task: (1) Name the three particles and their charges. (2) Find protons, neutrons and electrons from the atomic number and mass number. (3) Explain what an isotope is.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Hebrews 11:3 says, Through faith we understand that the worlds were framed by the word of God, so that things which are seen were not made of things which do appear. Atoms are too small to see, yet they build the visible world.\n\nNow watch this. The nucleus holds protons, which are positive, and neutrons, which have no charge. Electrons are negative and move around the nucleus in an electron cloud. An atom is mostly empty space. Rutherford learned this when most particles passed straight through gold foil and a few bounced back.\n\nLook at the numbers. The atomic number is the number of protons, and it identifies the element. The mass number is protons plus neutrons. Sodium has atomic number 11 and mass number 23, so it has 11 protons, 11 electrons and 12 neutrons.\n\nIsotopes are atoms of the same element with different numbers of neutrons. Carbon 12 has 6 neutrons. Carbon 14 has 8. An ion forms when an atom gains or loses electrons.\n\nYour task is to name the particles, find the numbers in an atom and explain isotopes. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 Atomic Structure and Isotopes$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 The Periodic Table$j$, $j${"readings": [{"title": "1 Corinthians 14 (King James Version)", "url": "/portal/bible/1Corinthians/14"}], "body": "The periodic table is an organized chart of the elements. First Corinthians 14:40 says, Let all things be done decently and in order. Order helps us find patterns, and the periodic table is one of the most useful charts in science.\n\nIn 1869 Dmitri Mendeleev arranged the known elements by atomic mass and left gaps for elements not yet discovered, correctly predicting some of their properties. The modern table arranges the elements by increasing atomic number, and 118 elements have been named. Each box shows the symbol, atomic number, name and atomic mass.\n\nA horizontal row is a period, and there are seven. A vertical column is a group or family, and there are eighteen. Elements in the same group have similar chemical properties because they have the same number of valence electrons, the electrons in the outermost energy level.\n\nThe table is divided into regions. Metals are on the left and center. They are generally shiny, malleable, ductile and good conductors of heat and electricity. Nonmetals are on the right and are generally dull, brittle as solids and poor conductors. Metalloids lie along the staircase between them and have properties of both. Group 1 contains the alkali metals, which are very reactive. Group 2 contains the alkaline earth metals. Groups 3 to 12 are the transition metals. Group 17 contains the halogens, which are very reactive nonmetals. Group 18 contains the noble gases, which are almost unreactive.\n\nThere are also trends. Moving left to right across a period, atoms generally get smaller and hold their electrons more tightly. Moving down a group, atoms get larger because they have more energy levels.\n\nYour task: (1) Tell what a period and a group are. (2) Locate metals, nonmetals and metalloids. (3) Explain why elements in one group behave alike.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, First Corinthians 14:40 says, Let all things be done decently and in order. Order helps us see patterns, and the periodic table is one of the most useful charts in science.\n\nNow watch this. Mendeleev arranged the elements in 1869 by atomic mass and left gaps for elements not yet found, and he predicted some of their properties correctly. The modern table is arranged by atomic number, and 118 elements have been named.\n\nLook at the layout. A horizontal row is a period, and there are seven. A vertical column is a group, and there are eighteen. Elements in a group behave alike because they have the same number of valence electrons.\n\nMetals are on the left and center. They are shiny, malleable and good conductors. Nonmetals are on the right. Metalloids lie along the staircase between them. Group 1 is the alkali metals. Group 17 is the halogens. Group 18 is the noble gases, which almost never react.\n\nMoving down a group, atoms get larger because they have more energy levels.\n\nYour task is to explain periods and groups, locate the regions and explain why a group behaves alike. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 The Periodic Table$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 Electrons and Energy Levels$j$, $j${"readings": [{"title": "Genesis 1 (King James Version)", "url": "/portal/bible/Genesis/1"}], "body": "Electrons are arranged around the nucleus in energy levels, sometimes called shells. Genesis 1:3 says, And God said, Let there be light: and there was light. Light and electrons are closely connected, because atoms give off light when their electrons move between energy levels.\n\nEach energy level can hold only a certain number of electrons. For the first 18 elements, the first level holds up to 2 electrons, the second holds up to 8, and the third holds up to 8. Electrons fill the lowest energy levels first. Sodium has 11 electrons, so its arrangement is 2, 8, 1. Chlorine has 17 electrons, arranged 2, 8, 7. Neon has 10 electrons, arranged 2, 8.\n\nThe electrons in the outermost energy level are the valence electrons. They determine how an atom reacts. For the main group elements, the number of valence electrons matches the group number, ignoring the tens digit. Group 1 has one valence electron, group 2 has two, group 17 has seven and group 18 has eight, except helium, which has two. An electron dot diagram shows the symbol with a dot for each valence electron.\n\nAtoms are most stable when the outer level is full, which for many atoms means eight electrons. This is the octet rule. Sodium can lose one electron to reach a full level and becomes a positive ion. Chlorine can gain one electron to reach a full level and becomes a negative ion. Noble gases already have full outer levels, so they rarely react.\n\nWhen an electron absorbs energy it jumps to a higher level, and when it falls back it releases energy, sometimes as light. Each element releases its own colors, which is why a flame test and a neon sign show different colors for different elements.\n\nYour task: (1) Write the electron arrangement of an element. (2) Find its valence electrons. (3) Predict whether it tends to gain or lose electrons.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Genesis 1:3 says, And God said, Let there be light: and there was light. Light and electrons are closely connected, because atoms give off light when their electrons move.\n\nNow watch this. Electrons sit in energy levels. For the first 18 elements, the first level holds up to 2 electrons, the second up to 8, and the third up to 8. Sodium has 11 electrons, arranged 2, 8, 1. Chlorine has 17, arranged 2, 8, 7.\n\nThe electrons in the outer level are the valence electrons, and they control how an atom reacts. Atoms are most stable with a full outer level, usually 8 electrons. That is the octet rule. Sodium loses one electron and becomes a positive ion. Chlorine gains one and becomes a negative ion. Noble gases already have full outer levels, so they rarely react.\n\nWhen an electron absorbs energy it jumps up, and when it falls back it releases energy, sometimes as light. That is why a neon sign glows with its own color.\n\nYour task is to write an electron arrangement, find valence electrons and predict gain or loss. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 Electrons and Energy Levels$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 Elements, Compounds and Mixtures$j$, $j${"readings": [{"title": "Psalm 104 (King James Version)", "url": "/portal/bible/Psalms/104"}], "body": "Matter can be sorted by what it is made of. Psalm 104:24 says, O LORD, how manifold are thy works! in wisdom hast thou made them all: the earth is full of thy riches. The variety of materials around us comes from a limited set of elements combined in many ways.\n\nA pure substance has a fixed composition. An element is a pure substance made of only one kind of atom, and it cannot be broken down into simpler substances by chemical means. Examples are gold, oxygen and iron. A compound is a pure substance made of two or more elements chemically combined in a fixed ratio. Water is a compound written H2O, which means two hydrogen atoms for each oxygen atom. Table salt, NaCl, has one sodium atom for each chlorine atom, and carbon dioxide, CO2, has one carbon and two oxygen atoms. A compound has properties different from its elements, and it can be separated only by a chemical change.\n\nA mixture is two or more substances that are together but not chemically combined. Each substance keeps its own properties, and the amounts can vary. A heterogeneous mixture, such as a salad or sand in water, is not evenly mixed. A homogeneous mixture, also called a solution, is evenly mixed throughout. Salt water is a solution, with salt as the solute and water as the solvent. Air is a solution of gases, about 78 percent nitrogen and 21 percent oxygen. Steel is a solid solution of iron and carbon.\n\nMixtures are separated by physical methods. A magnet pulls iron filings from sand. Filtering separates a solid from a liquid. Evaporation leaves the dissolved salt behind. Distillation separates liquids by their boiling points. Chromatography separates colors in an ink.\n\nYour task: (1) Sort examples into elements, compounds and mixtures. (2) Read a chemical formula. (3) Choose a method to separate a mixture.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Psalm 104:24 says, O LORD, how manifold are thy works! in wisdom hast thou made them all. The variety around us comes from a limited set of elements combined in many ways.\n\nNow watch this. An element is made of only one kind of atom, like gold or oxygen. A compound is two or more elements chemically combined in a fixed ratio. Water, H2O, has two hydrogen atoms for each oxygen atom. Salt, NaCl, has one sodium for each chlorine. A compound has properties different from its elements and needs a chemical change to separate it.\n\nLook at mixtures. A mixture is substances together but not chemically combined, and each keeps its own properties. A salad is heterogeneous. Salt water is homogeneous, also called a solution, with salt as the solute and water as the solvent. Air is a solution of gases, about 78 percent nitrogen and 21 percent oxygen.\n\nMixtures are separated by physical methods. A magnet pulls iron from sand. Filtering separates a solid from a liquid. Evaporation leaves salt behind. Distillation separates liquids by boiling point.\n\nYour task is to sort examples, read a formula and choose a separation method. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 Elements, Compounds and Mixtures$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Atoms and the Periodic Table$j$, $j${"prompt": "Write a report of at least 250 words on atoms and the periodic table. Use complete sentences, show your work and label each part. Hebrews 11:3 says, Through faith we understand that the worlds were framed by the word of God, so that things which are seen were not made of things which do appear.\n\nPart 1: An atom has atomic number 17 and mass number 35. Find its protons, neutrons and electrons, and tell what element it is.\nPart 2: Explain what isotopes are, using carbon 12 and carbon 14 as your example.\nPart 3: Describe how the periodic table is organized, define period and group, and explain why sodium and potassium react in similar ways.\nPart 4: Write the electron arrangement of magnesium, which has 12 electrons, and of fluorine, which has 9 electrons. Give the valence electrons of each and predict the charge each forms as an ion.\nPart 5: Classify salt water, gold, carbon dioxide and a salad as an element, a compound or a mixture, and describe how to separate a mixture of sand, salt and iron filings.", "rubric": "100 points. Part 1: 20 points. Part 2: 15 points. Part 3: 20 points. Part 4: 25 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Atoms and the Periodic Table$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Order in the Unseen$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes something you cannot see that you know is real, (2) explains how the order of the periodic table helps scientists predict what elements will do, (3) explains what it teaches us that a few kinds of atoms make up so many materials, and (4) connects your answer to First Corinthians 14:40, Hebrews 11:3 or Psalm 104:24. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How does the order we see in the periodic table point to a wise Creator? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Order in the Unseen$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: Atomic Structure and Isotopes$j$, $j${"questions": [{"q": "The particle with a positive charge found in the nucleus is the:", "options": ["Electron", "Neutron", "Ion", "Proton"]}, {"q": "An atom has 11 protons and 12 neutrons. Its mass number is:", "options": ["23", "12", "11", "1"]}, {"q": "Atoms of the same element with different numbers of neutrons are:", "options": ["Ions", "Isotopes", "Compounds", "Molecules"]}, {"q": "Rutherford's gold foil experiment showed that an atom has:", "options": ["A small dense nucleus", "No electrons", "A solid positive sphere", "Uniform charge throughout"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Atomic Structure and Isotopes$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,1,0}'::int[], array[$j$Protons are positive and are in the nucleus.$j$,$j$11 plus 12 equals 23.$j$,$j$Different neutron counts make isotopes.$j$,$j$A few particles bounced back from a tiny dense nucleus.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Atomic Structure and Isotopes$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: The Periodic Table$j$, $j${"questions": [{"q": "A horizontal row on the periodic table is called a:", "options": ["Group", "Isotope", "Block", "Period"]}, {"q": "Elements in the same group have similar properties because they have the same number of:", "options": ["Protons", "Neutrons", "Valence electrons", "Total electrons"]}, {"q": "The elements in Group 18 are the:", "options": ["Halogens", "Noble gases", "Alkali metals", "Transition metals"]}, {"q": "The modern periodic table is arranged by increasing:", "options": ["Atomic number", "Melting point", "Density", "Number of neutrons"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: The Periodic Table$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,1,0}'::int[], array[$j$Rows are periods.$j$,$j$Valence electrons control chemical behavior.$j$,$j$Group 18 holds the noble gases.$j$,$j$Atomic number orders the modern table.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: The Periodic Table$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: Electrons and Energy Levels$j$, $j${"questions": [{"q": "The maximum number of electrons in the first energy level is:", "options": ["8", "1", "18", "2"]}, {"q": "Sodium has 11 electrons. Its electron arrangement is:", "options": ["8, 3", "2, 9", "2, 2, 7", "2, 8, 1"]}, {"q": "Electrons in the outermost energy level are called:", "options": ["Core electrons", "Isotopes", "Valence electrons", "Nuclear particles"]}, {"q": "An atom with a full outer energy level is generally:", "options": ["Stable and unreactive", "Positively charged", "Highly reactive", "Radioactive"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Electrons and Energy Levels$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,2,0}'::int[], array[$j$The first level holds only 2.$j$,$j$Fill 2, then 8, then the last 1.$j$,$j$Valence electrons are in the outer level.$j$,$j$A full outer level makes an atom stable.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Electrons and Energy Levels$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Elements, Compounds and Mixtures$j$, $j${"questions": [{"q": "A pure substance made of two or more elements chemically combined is a:", "options": ["Element", "Mixture", "Compound", "Solution"]}, {"q": "Salt water is an example of a:", "options": ["Heterogeneous mixture", "Homogeneous mixture", "Compound", "Element"]}, {"q": "Which method best separates iron filings from sand?", "options": ["Distillation", "Using a magnet", "Evaporation", "Chemical decomposition"]}, {"q": "The formula H2O shows that water has:", "options": ["1 atom of each element", "2 oxygen atoms and 1 hydrogen atom", "2 hydrogen atoms and 1 oxygen atom", "2 compounds"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Elements, Compounds and Mixtures$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,1,2}'::int[], array[$j$A compound has a fixed ratio of elements.$j$,$j$Salt water is evenly mixed, so it is a solution.$j$,$j$Iron is attracted to a magnet and sand is not.$j$,$j$The subscript 2 follows the hydrogen.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Elements, Compounds and Mixtures$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: Atoms and the Periodic Table$j$, $j${"questions": [{"q": "The atomic number of an element equals its number of:", "options": ["Protons", "Energy levels", "Isotopes", "Neutrons"]}, {"q": "A neutral atom with atomic number 17 has how many electrons?", "options": ["18", "17", "1", "35"]}, {"q": "Carbon 12 and carbon 14 differ in their number of:", "options": ["Protons", "Electrons only", "Atomic number", "Neutrons"]}, {"q": "Mendeleev first arranged the elements by:", "options": ["Atomic mass", "Date of discovery", "Atomic number", "Color"]}, {"q": "Metals are generally:", "options": ["Good conductors of heat and electricity", "Mostly gases at room temperature", "Poor conductors of electricity", "Always brittle"]}, {"q": "Chlorine has 7 valence electrons, so it tends to:", "options": ["Lose seven electrons", "Lose one electron", "Gain one electron", "Share no electrons"]}, {"q": "Which is a heterogeneous mixture?", "options": ["Salt water", "Air", "A salad", "Steel"]}, {"q": "Which cannot be broken down into simpler substances by chemical means?", "options": ["A mixture", "A solution", "A compound", "An element"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Atoms and the Periodic Table$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,3,0,0,2,2,3}'::int[], array[$j$Atomic number counts protons.$j$,$j$Neutral atoms have as many electrons as protons.$j$,$j$They are isotopes with different neutron counts.$j$,$j$Mendeleev used atomic mass and left gaps.$j$,$j$Metals conduct heat and electricity well.$j$,$j$Gaining one electron gives a full outer level.$j$,$j$A salad is not evenly mixed.$j$,$j$An element is made of one kind of atom.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Atoms and the Periodic Table$j$ on conflict (item_id) do nothing;
